INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("たまには\n協力するのもいいんじゃない？\nあたしも手を貸してあげる", -363, 1, 0, "2030/12/17 14:59:59", 0, 7, 7001, "キャル", 0, 1, 0, 106001, "2015/12/17 15:00:00", 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("多くの方と協力して\n戦えるようです\n主さまなら、さぞ\nご活躍なさることでしょう", -363, 1, 0, "2030/12/17 14:59:59", 0, 7, 7002, "コッコロ", 0, 1, 0, 105901, "2015/12/17 15:00:00", 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("たくさんの人と一緒に\n協力バトルです！\nがんばりましょう☆", -363, 1, 0, "2030/12/17 14:59:59", 0, 7, 7003, "ペコリーヌ", 0, 1, 0, 105801, "2015/12/17 15:00:00", 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("ジュエルを食べ物…\nいえ、貴重品と交換できます！", -363, 1, 0, "2030/12/17 14:59:59", 0, 10, 10001, "ペコリーヌ", 0, 1, 0, 105801, "2015/12/17 15:00:00", 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("ジュエルはよく考えて\n使うことね\n無駄遣い厳禁！", -363, 1, 0, "2030/12/17 14:59:59", 0, 10, 10002, "キャル", 0, 1, 0, 106001, "2015/12/17 15:00:00", 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("主さまのジュエルで\n貴重な品々を購入できます\nですが、無駄遣いは\n『めっ』でございますよ", -363, 1, 0, "2030/12/17 14:59:59", 0, 10, 10003, "コッコロ", 0, 1, 0, 105901, "2015/12/17 15:00:00", 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("ジュエルがあれば\n貴重品と交換できるみたい\n大事に使いましょうね", -363, 1, 0, "2030/12/17 14:59:59", 0, 10, 10004, "シェフィ", 2104010, 2, 0, 106401, "2015/12/17 15:00:00", 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("特定の条件を達成すると\n報酬がもらえますよ！\nがんばりましょう♪　", -416.5, 1, 0, "2030/12/17 14:59:59", 0, 12, 12001, "ペコリーヌ", 0, 1, 0, 105801, "2015/12/17 15:00:00", 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("思い出が詰まってるって\nいろいろあったけど\n振り返るのもいいんじゃない？", -363, 1, 0, "2030/12/17 14:59:59", 0, 13, 13001, "キャル", 0, 1, 0, 106001, "2015/12/17 15:00:00", 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("主さまとの楽しい日々…\nこちらで何度でも\n思い返しましょう♪", -363, 1, 0, "2030/12/17 14:59:59", 0, 13, 13002, "コッコロ", 0, 1, 0, 105901, "2015/12/17 15:00:00", 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("みんなとの大切な思い出が\nたくさん詰まってるのね\n一緒に振り返って、\n心に刻みたいわ", -363, 1, 0, "2030/12/17 14:59:59", 0, 13, 13003, "シェフィ", 2104010, 2, 0, 106401, "2015/12/17 15:00:00", 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("女の子との思い出が\nたくさん見られますよ！\nヒューヒュー♪\nモテモテですねー☆", -363, 1, 0, "2030/12/17 14:59:59", 0, 13, 13004, "ペコリーヌ", 0, 1, 0, 105801, "2015/12/17 15:00:00", 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("育成に必要なアイテムが\n獲得できるクエストです\nわたくし、主さまのために、\n強くなりますよ", -363, 1, 0, "2030/12/17 14:59:59", 0, 14, 14001, "コッコロ", 0, 1, 0, 105901, "2015/12/17 15:00:00", 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("このクエストを攻略すると、\nアイテムが手に入るらしいわ。\nもっと強くなるために、\n一生懸命がんばるわね！", -363, 1, 0, "2030/12/17 14:59:59", 0, 14, 14002, "シェフィ", 2104010, 2, 0, 106401, "2015/12/17 15:00:00", 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("このクエストを攻略すれば、\nアイテムがもらえますよ\nたくさん集めて、どんどん\n強くなっちゃいましょう！", -363, 1, 0, "2030/12/17 14:59:59", 0, 14, 14003, "ペコリーヌ", 0, 1, 0, 105801, "2015/12/17 15:00:00", 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("クエストを攻略すると、\nアイテムが手に入るんだって\nもらえるものは、\nもらっておきましょ！", -363, 1, 0, "2030/12/17 14:59:59", 0, 14, 14004, "キャル", 0, 1, 0, 106001, "2015/12/17 15:00:00", 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("主さま、旅の準備を整えて\nより充実した冒険をいたし\nましょう", -470, 1, 0, "2030/12/17 14:59:59", 0, 15, 15001, "コッコロ", 0, 1, 0, 105901, "2015/12/17 15:00:00", 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("ねぇ…クランに加入してみない？\n一人も楽しいけど、みんなと\n一緒も賑やかでいいと思うの", -363, 1, 0, "2030/12/17 14:59:59", 0, 16, 16001, "シェフィ", 2104010, 2, 0, 106401, "2015/12/17 15:00:00", 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("クランに加入してみませんか？\nみんなといっしょに冒険した方が、\n楽しいですよ！", -363, 1, 0, "2030/12/17 14:59:59", 0, 16, 16002, "ペコリーヌ", 0, 1, 0, 105801, "2015/12/17 15:00:00", 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("クランに入れるらしいわよ\nせっかくだから入ってみたら？\nけっこう楽しいみたいよ♪", -363, 1, 0, "2030/12/17 14:59:59", 0, 16, 16003, "キャル", 0, 1, 0, 106001, "2015/12/17 15:00:00", 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("こちらでクランに加入できます\n素敵なクランがたくさんあって、\n目移りしてしまいますね", -363, 1, 0, "2030/12/17 14:59:59", 0, 16, 16004, "コッコロ", 0, 1, 0, 105901, "2015/12/17 15:00:00", 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (" こちらではクランバトルに\n 参加された仲間のみなさんの\n 活躍を振り返ることができます", -363, 1, 0, "2030/12/17 14:59:59", 0, 17, 17002, "コッコロ", 0, 1, 0, 105901, "2015/12/17 15:00:00", 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("模擬戦の戦績もアンタが\n気に入ったものがあれば\n記録しておけるのね", -363, 1, 0, "2030/12/17 14:59:59", 0, 25, 17004, "キャル", 0, 1, 0, 106001, "2015/12/17 15:00:00", 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("主さま、今回のクランバトルでの\nご活躍が記録されています\nバトルの参考にいたしましょう", -363, 1, 0, "2030/12/17 14:59:59", 0, 25, 17005, "コッコロ", 0, 1, 0, 105901, "2015/12/17 15:00:00", 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("今回のクランバトルの調子は\nどうかしら？\n戦績を見れば、次のバトルに\n活かせるかもしれないわ", -363, 1, 0, "2030/12/17 14:59:59", 0, 25, 17006, "シェフィ", 2104010, 2, 0, 106401, "2015/12/17 15:00:00", 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("今回のクランバトルでの戦績を\nおさらいできますよ！\n私にも見せてください☆", -363, 1, 0, "2030/12/17 14:59:59", 0, 25, 17007, "ペコリーヌ", 0, 1, 0, 105801, "2015/12/17 15:00:00", 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("ようこそ！\nこちらでは、\nギルドハウスで流れる音楽の\n変更や購入が出来ますよ", -363, 1, 0, "2030/12/17 14:59:59", 0, 18, 18001, "カリン", 0, 1, 0, 190801, "2015/12/17 15:00:00", 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("ＢＧＭの変更や購入は、こちらから\nできますよ\n素敵な音楽を、たくさんご用意\nいたしました！", -363, 1, 0, "2030/12/17 14:59:59", 0, 18, 18002, "カリン", 0, 1, 0, 190801, "2015/12/17 15:00:00", 2);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("ギルドハウスの\nＢＧＭを変更できますよ\nあなたの好きな曲、\n私にも聴かせてくださいね", -470, 1, 0, "2030/12/17 14:59:59", 0, 19, 19001, "カリン", 0, 1, 0, 190801, "2015/12/17 15:00:00", 3);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("こちらでは、ＢＧＭの変更が\nできますよ\nどんな曲に変更しますか？\nふふふ、私も楽しみです♪", -470, 1, 0, "2030/12/17 14:59:59", 0, 19, 19002, "カリン", 0, 1, 0, 190801, "2015/12/17 15:00:00", 4);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("こちらでは、ＢＧＭを購入\nすることができますよ\n試聴することもできるので、\nじっくり選んでくださいね", -470, 1, 0, "2030/12/17 14:59:59", 0, 20, 20001, "カリン", 0, 1, 0, 190801, "2015/12/17 15:00:00", 5);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("いらっしゃいませ！\nＢＧＭの購入はこちらです\n素敵な曲がたくさんあって、\n目移りしちゃいますね", -470, 1, 0, "2030/12/17 14:59:59", 0, 20, 20002, "カリン", 0, 1, 0, 190801, "2015/12/17 15:00:00", 6);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("ここで手に入れたアイテムで\n専用装備を作成できるみたいね\nアイテムが集まったら\nさっそく作ってみましょ！", -363, 1, 0, "2030/12/17 14:59:59", 0, 21, 21001, "キャル", 0, 1, 0, 106001, "2015/12/17 15:00:00", 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("攻略すると珍しいアイテムが\n手に入りますよ\nこのアイテムで専用装備を\n作成できるようです", -363, 1, 0, "2030/12/17 14:59:59", 0, 21, 21002, "コッコロ", 0, 1, 0, 105901, "2015/12/17 15:00:00", 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("専用装備が欲しいなら\nこのクエストに挑戦するといいわ\n集めた素材でもっともっと\n強くなりましょう", -363, 1, 0, "2030/12/17 14:59:59", 0, 21, 21003, "シェフィ", 2104010, 2, 0, 106401, "2015/12/17 15:00:00", 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("専用装備の作成に必要な\nアイテムを獲得できますよ\nたくさん集めてどんどん\n強くなりましょう！", -363, 1, 0, "2030/12/17 14:59:59", 0, 21, 21004, "ペコリーヌ", 0, 1, 0, 105801, "2015/12/17 15:00:00", 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("投票はこちらです\nあなたが応援したい女の子に\n思いを込めた一票を\nお願いします！", -430, 1, 0, "2030/12/17 14:59:59", 0, 22, 22001, "カリン", 0, 1, 0, 190801, "2015/12/17 15:00:00", 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("ようこそ！\nあなたが思いを寄せるのは\nどの女の子ですか？\n応援してあげてくださいね！", -430, 1, 0, "2030/12/17 14:59:59", 0, 22, 22002, "カリン", 0, 1, 0, 190801, "2015/12/17 15:00:00", 2);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("たくさんの投票、\nありがとうございました\n結果発表を楽しみに\n待っていてくださいね！", -430, 1, 0, "2030/12/17 14:59:59", 0, 23, 23001, "カリン", 0, 1, 0, 190801, "2015/12/17 15:00:00", 3);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("ただ今、人気投票の\n集計中です\n結果が出るまでもう少しだけ\nお待ちくださいね", -430, 1, 0, "2030/12/17 14:59:59", 0, 23, 23002, "カリン", 0, 1, 0, 190801, "2015/12/17 15:00:00", 4);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("あなた様が手伝ってくださった\nチョコレートケーキ\n美味しくないはずがありませんわ", -385, 2, 10011, "2030/12/17 14:59:59", 8, 24, 24001, "エリコ（バレンタイン）", 0, 1, 4.08, 109001, "2019/01/31 12:00:00", 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("このような失敗、あなた様が\nするはずありません\nもう一度挑戦してみましょう", -385, 2, 10011, "2030/12/17 14:59:59", 8, 24, 24002, "エリコ（バレンタイン）", 0, 1, 5, 109001, "2019/01/31 12:00:00", 2);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("あなた様のために\n作っているケーキを\nあなた様に手伝っていただく……\nことになるなんて……クスクス", -385, 2, 10011, "2030/12/17 14:59:59", 8, 24, 24003, "エリコ（バレンタイン）", 0, 1, 10.11, 109001, "2019/01/31 12:00:00", 3);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("あまり気に病む必要はありませんわ\nこれからは私がたっぷりと\n時間をかけて教えて差し上げますから", -385, 2, 10011, "2030/12/17 14:59:59", 8, 24, 24004, "エリコ（バレンタイン）", 0, 1, 4, 109001, "2019/01/31 12:00:00", 4);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("今回は調子が悪かった……のですか？\nあなた様が手伝ってくれたものなら\nわたしはどんなものでも……クスクス", -385, 2, 10011, "2030/12/17 14:59:59", 8, 24, 24005, "エリコ（バレンタイン）", 0, 1, 6, 109001, "2019/01/31 12:00:00", 5);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("あなた様が手がけた\nチョコレートケーキは\n私にとっての宝物……\n侮辱する者は生かしておきませんわ", 0, 1, 10011, "2030/12/17 14:59:59", 0, 24, 24006, "エリコ（バレンタイン）", 0, 1, 0, 109002, "2019/01/31 12:00:00", 6);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("とても素晴らしい出来栄えですわ！\nあなた様にふさわしい\nチョコレートケーキができました", 0, 1, 10011, "2030/12/17 14:59:59", 0, 24, 24007, "エリコ（バレンタイン）", 0, 1, 0, 109002, "2019/01/31 12:00:00", 7);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("私を手伝ってくれたあなた様は\nすでに私の虜……\n甘い世界に誘って差し上げますわ", 0, 1, 10011, "2030/12/17 14:59:59", 0, 24, 24008, "エリコ（バレンタイン）", 0, 1, 0, 109002, "2019/01/31 12:00:00", 8);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("あなた様の愛情\nしかと受け止めました\nこれが……私たちの初めての\n共同作業ですわね……クスクス", 0, 1, 10011, "2030/12/17 14:59:59", 0, 24, 24009, "エリコ（バレンタイン）", 0, 1, 0, 109002, "2019/01/31 12:00:00", 9);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("これは世界一の\nチョコレートケーキですわ\nだって、あなた様が腕によりをかけて\n作ってくださったんですもの", 0, 1, 10011, "2030/12/17 14:59:59", 0, 24, 24010, "エリコ（バレンタイン）", 0, 1, 0, 109002, "2019/01/31 12:00:00", 10);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("上手にできなくて残念だった？\nでも、弟くんの気持ちが嬉しいな\nいつだってお姉ちゃんは\nそばにいるからね♪", -385, 2, 10011, "2030/12/17 14:59:59", 8, 24, 24011, "シズル（バレンタイン）", 0, 1, 2.12, 109101, "2019/01/31 12:00:00", 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("うーん、弟くんには珍しく\n緊張しちゃったのかな？\nもう一度チャレンジしてみる？", -385, 2, 10011, "2030/12/17 14:59:59", 8, 24, 24012, "シズル（バレンタイン）", 0, 5, 4.19, 109101, "2019/01/31 12:00:00", 2);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("お姉ちゃんのお手伝い、\nよくできました！\nあー、\nまだつまみ食いしちゃダメだぞ！", -385, 4, 10011, "2030/12/17 14:59:59", 8, 24, 24013, "シズル（バレンタイン）", 0, 2, 2.3, 109101, "2019/01/31 12:00:00", 3);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("見てみて！\nスポンジに綺麗な焼き目がついてるよ\nさっすが弟くんだね！", 0, 1, 10011, "2030/12/17 14:59:59", 0, 24, 24014, "シズル（バレンタイン）", 0, 1, 0, 109102, "2019/01/31 12:00:00", 4);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("まぁまぁ、落ち込まないで\n見た目は……個性的だけど、\n味は絶対美味しいはずだから！", -385, 2, 10011, "2030/12/17 14:59:59", 8, 24, 24015, "シズル（バレンタイン）", 0, 5, 5.23, 109101, "2019/01/31 12:00:00", 5);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("弟くんみたいな\n可愛いケーキができたよ！\n早く食べてみたいでしょ♪", 0, 1, 10011, "2030/12/17 14:59:59", 0, 24, 24016, "シズル（バレンタイン）", 0, 1, 0, 109102, "2019/01/31 12:00:00", 6);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("あれれ？　弟くん、指に\nチョコレートがくっついてるよ？\nお姉ちゃんが舐めてあげるね、\nはぁむ！", -385, 2, 10011, "2030/12/17 14:59:59", 8, 24, 24017, "シズル（バレンタイン）", 0, 1, 5.01, 109101, "2019/01/31 12:00:00", 7);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("なかなか上手にできたんじゃない？\nでも弟くんはまだまだできる子！\nお姉ちゃん、信じてるからね", 0, 1, 10011, "2030/12/17 14:59:59", 0, 24, 24018, "シズル（バレンタイン）", 0, 1, 0, 109102, "2019/01/31 12:00:00", 8);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("わぁ～、\nとっても美味しそうにできたね！\n弟くん手慣れてたから\nお姉ちゃん安心して任せられちゃった！", 0, 1, 10011, "2030/12/17 14:59:59", 0, 24, 24019, "シズル（バレンタイン）", 0, 1, 0, 109102, "2019/01/31 12:00:00", 9);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("や～ん、弟くんが手伝ってくれた\nチョコレートケーキ！\nすっごく美味しそうにできたね♪", 0, 1, 10011, "2030/12/17 14:59:59", 0, 24, 24020, "シズル（バレンタイン）", 0, 1, 0, 109102, "2019/01/31 12:00:00", 10);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("ここから先は神聖な場所みたい\nどんなお宝が眠っているのか、\n今から探索するのが楽しみね♪", -363, 1, 0, "2030/12/17 14:59:59", 0, 26, 26001, "シェフィ", 2104010, 2, 0, 106401, "2015/12/17 15:00:00", 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("ここから先は神聖な場所\nみたいです！\nどんなお宝が手に入るか\n楽しみですね！", -363, 1, 0, "2030/12/17 14:59:59", 0, 26, 26002, "ペコリーヌ", 0, 1, 0, 105801, "2015/12/17 15:00:00", 1);
