INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("ここにさらなる力を得るための\nアイテムが眠っているみたい\nです！　どこから挑戦するか\n迷っちゃいますね！", -363, 1, 0, "2030/12/17 14:59:59", 0, 27, 27002, "ペコリーヌ", 0, 1, 0, 105801, "2015/12/17 15:00:00", 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("ここにさらなる力を得るための\nアイテムが眠っているみたい！\nどんどん挑戦して\n強くなっちゃいましょ！", -363, 1, 0, "2030/12/17 14:59:59", 0, 27, 27003, "キャル", 0, 1, 0, 106001, "2015/12/17 15:00:00", 1);
