INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("過去のストーリーイベントを\n楽しめちゃいますよ！\n遊んだことのないものがあれば\n一緒にやってみましょう♪", -458, 2, 0, "2030/12/17 14:59:59", 0, 38, 38001, "ペコリーヌ", 0, 1, 5.3, 105801, "2015/12/17 15:00:00", 1);
