INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("", 9999, 3, 0, "2020/04/08 23:59:59", 9999, 39, 39005, "ペコリーヌ", 0, 3, 0, 105801, "2020/04/01", 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("これまでに出題された\n問題を振り返ることが\nできますよ\n復習は大切です♪", -430, 1, 0, "2030/12/17 14:59:59", 0, 40, 40001, "カリン", 0, 1, 0, 190801, "2015/12/17 15:00:00", 2);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("ここでは腕試しが\nできるんですって。\n自分の実力を測るのに、\nちょうどよさそうね。", -363, 1, 0, "2030/12/17 14:59:59", 0, 41, 41001, "シェフィ", 2104010, 1, 0, 106401, "2015/12/17 15:00:00", 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("ここで腕試しを\nしていきましょう！\n全力全開、\nがんばっちゃいますよ～！", -363, 1, 0, "2030/12/17 14:59:59", 0, 41, 41002, "ペコリーヌ", 0, 1, 0, 105801, "2015/12/17 15:00:00", 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("ここで腕試しが\nできるみたいね。\n試してみるのも\nいいんじゃない？", -363, 1, 0, "2030/12/17 14:59:59", 0, 41, 41003, "キャル", 0, 1, 0, 106001, "2015/12/17 15:00:00", 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("腕試しができるようです。\nここで練習を重ね、実戦に\n活かしてまいりましょう。", -363, 1, 0, "2030/12/17 14:59:59", 0, 41, 41004, "コッコロ", 0, 1, 0, 105901, "2015/12/17 15:00:00", 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("訓練の成果に応じて、\n報酬がもらえるそうです。\n共に励んでいきましょう。", -416.5, 1, 0, "2030/12/17 14:59:59", 0, 42, 42001, "コッコロ", 0, 1, 0, 105901, "2015/12/17 15:00:00", 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("目標を達成すれば、\n報酬がもらえるみたい。\n頑張り甲斐があるわね。", -416.5, 1, 0, "2030/12/17 14:59:59", 0, 42, 42002, "シェフィ", 2104010, 1, 0, 106401, "2015/12/17 15:00:00", 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("腕試しをがんばれば、\n報酬がもらえますよ。\n挑戦していきましょう☆", -416.5, 1, 0, "2030/12/17 14:59:59", 0, 42, 42003, "ペコリーヌ", 0, 1, 0, 105801, "2015/12/17 15:00:00", 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("ミッションを達成すると、\n報酬が出るんですって。\n一緒にやってみましょ！", -416.5, 1, 0, "2030/12/17 14:59:59", 0, 42, 42004, "キャル", 0, 1, 0, 106001, "2015/12/17 15:00:00", 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("ここからアリーナに\n挑戦できますよ！\n編成を工夫してライバルに\n挑んじゃいましょう！", -363, 1, 0, "2030/12/17 14:59:59", 0, 43, 43001, "ペコリーヌ", 0, 1, 0, 105801, "2015/12/17 15:00:00", 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("こちらからアリーナに\n挑戦することができます。\n主さまらしい編成で\nライバルに挑みましょう。", -363, 1, 0, "2030/12/17 14:59:59", 0, 43, 43002, "コッコロ", 0, 1, 0, 105901, "2015/12/17 15:00:00", 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("ここからアリーナに\n挑戦できるわよ！\nしっかり編成を考えて\nライバルに挑みなさい！", -363, 1, 0, "2030/12/17 14:59:59", 0, 43, 43003, "キャル", 0, 1, 0, 106001, "2015/12/17 15:00:00", 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("ミッションをクリアすると報酬が\n受け取れるわ。ジャンジャン\nクリアしてバリバリ強化して\nあげなさい♪", -416.5, 1, 0, "2030/12/17 14:59:59", 0, 44, 43004, "アメス", 0, 1, 0, 123001, "2015/12/17 15:00:00", 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("ぼんやりしてる場合じゃないわ。\n早くミッションをクリアして\n報酬を受け取ってきなさい！", -416.5, 1, 0, "2030/12/17 14:59:59", 0, 44, 43005, "アメス", 0, 1, 0, 123001, "2015/12/17 15:00:00", 2);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("ちょっとあんた、報酬が\n受け取れるじゃない！\n忘れずにチェックなさい。\nアメス様との約束よ？", -416.5, 2, 0, "2030/12/17 14:59:59", 0, 45, 43006, "アメス", 0, 1, 5.79, 123001, "2015/12/17 15:00:00", 3);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("はい、お疲れさま。\nここではマスタリーチケットを\n使って、マスタリー強化素材を\n手に入れることができるわよ。", -371.5, 1, 0, "2030/12/17 14:59:59", 0, 46, 46001, "アメス", 0, 1, 0, 123001, "2015/12/17 15:00:00", 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("呼ばれて飛び出てお姉ちゃんだよ♪\nたとえ火の中、水の中、迷宮の中っ\nこのダンジョンを踏破できるよう\n弟くんを応援してあげるからねっ♪", -416.5, 2, 0, "2030/12/17 14:59:59", 0, 47, 47001, "シズル", 0, 2, 0, 104901, "2015/12/17 15:00:00", 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("ほんとーに不思議な場所ですね～\nお兄ちゃんが冒険を頑張れるよう\nおまじないをかけてあげますねっ\nフレーフレー、お・兄・ちゃんっ♪", -416.5, 2, 0, "2030/12/17 14:59:59", 0, 47, 47002, "リノ", 0, 1, 9.32, 101101, "2015/12/17 15:00:00", 1);
